    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Ansi)]
    public struct NonBlit { public int Key; [MarshalAs(UnmanagedType.U1)] public bool Flag; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 6)] public string Name; public double D; }
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] public delegate int StrLenCb([MarshalAs(UnmanagedType.LPUTF8Str)] string s);
