    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] public delegate long SumBytesCb([In, MarshalAs(UnmanagedType.LPArray, SizeParamIndex = 1)] byte[] a, int n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] public delegate int BoolsCb([MarshalAs(UnmanagedType.U1)] bool a, [MarshalAs(UnmanagedType.Bool)] bool b, [MarshalAs(UnmanagedType.Bool)] bool c, [MarshalAs(UnmanagedType.I1)] bool d);
