    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] public delegate long RefsCb(ref int x, out long y, in double z, ref NonBlit s);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] public delegate long StructValCb(NonBlit s, int k);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] [return: MarshalAs(UnmanagedType.LPUTF8Str)] public delegate string RetStrCb(int n);
