    private static string s_lastString;
    private static int[] s_lastArray;
    private static readonly StrLenCb s_strLen = s => { s_lastString = s; return s?.Length ?? -1; };
    private static readonly WStrLenCb s_wstrLen = s => { s_lastString = s; return s?.Length ?? -1; };
    private static readonly AnsiStrLenCb s_ansiStrLen = s => { s_lastString = s; return s?.Length ?? -1; };
    private static readonly SumArrCb s_sumArr = (a, n) => { s_lastArray = a; long h = 0; foreach (int x in a ?? []) h = unchecked(h * 31 + x); return unchecked(h + (a?.Length ?? -1) * 1000003L); };
    private static readonly FillArrCb s_fillArr = (a, n, v) => { for (int i = 0; i < (a?.Length ?? 0); i++) a[i] = unchecked(v + i); return a?.Length ?? -1; };
    private static readonly SumBytesCb s_sumBytes = (a, n) => unchecked(Fold(a) + (a?.Length ?? -1) * 1000003L);
    private static readonly BoolsCb s_bools = (a, b, c, d) => (a ? 1 : 0) | (b ? 2 : 0) | (c ? 4 : 0) | (d ? 8 : 0);
    private static readonly CharsCb s_chars = (a, b, c) => a + 3 * b + 5 * c;
    private static readonly RefsCb s_refs = (ref int x, out long y, in double z, ref NonBlit s) => { long r = unchecked(x * 7L + BitConverter.DoubleToInt64Bits(z) + s.Key + (s.Flag ? 1 : 0) + (s.Name?.Length ?? -1)); x = unchecked(x + 1); y = r; s.Key = unchecked(s.Key * 2); s.Flag = !s.Flag; s.Name = "ok"; s.D = z; return r; };
    private static readonly StructValCb s_structVal = (s, k) => unchecked(s.Key + k * 1000003L + (s.Flag ? 1 : 0) + (s.Name?.Length ?? -1) * 7 + BitConverter.DoubleToInt64Bits(s.D));
    private static readonly RetStrCb s_retStr = n => n < 0 ? null : new string('x', n % 100) + n;

    public static void Run(ReadOnlySpan<byte> data)
    {
        var input = new FuzzInput(data);
        int which = input.Byte();
        switch (which % 32)
        {
            case 0: StructS4(ref input); break;
            case 1: StructS8(ref input); break;
            case 2: StructS8D(ref input); break;
            case 3: StructS12(ref input); break;
            case 4: StructS16(ref input); break;
            case 5: StructS16D(ref input); break;
            case 6: StructS16F(ref input); break;
            case 7: StructS20(ref input); break;
            case 8: StructS24(ref input); break;
            case 9: StructS32(ref input); break;
            case 10: StructS3(ref input); break;
            case 11: StructS6(ref input); break;
            case 12: StructS7(ref input); break;
            case 13: StructS9(ref input); break;
            case 14: StructSFI(ref input); break;
            case 15: StructSDI(ref input); break;
            case 16: StructSNested(ref input); break;
            case 17: StructSHalf(ref input); break;
            case 18: StructSGuid(ref input); break;
            case 19: StructSPtrB(ref input); break;
            case 20: StructSFloat3(ref input); break;
            case 21: StructSDoubleFloat(ref input); break;
            case 22: StructSByteFloat(ref input); break;
            case 23: StructSLongByte(ref input); break;
            case 24: StructSFloatLong(ref input); break;
            case 25: StructSHalf3(ref input); break;
            case 26: StructS40(ref input); break;
            case 27: StructSNested24(ref input); break;
            case 28: ScalarCases(ref input); break;
            case 29: DelegateCases(ref input); break;
            case 30: ReverseStrings(ref input); break;
            default: ReverseValues(ref input); break;
