        long expected = unchecked(a + 3L * b + 5L * c + 7L * d + 11L * e + 13L * f + 17L * g + 19L * (long)h + 23L * BitConverter.SingleToInt32Bits(i) + 29L * BitConverter.DoubleToInt64Bits(j) + 31L * k + 37L * l + 41L * m + 43L * BitConverter.SingleToInt32Bits(n) + 47L * BitConverter.DoubleToInt64Bits(o) + 53L * p + 59L * BitConverter.DoubleToInt64Bits(q) + 61L * BitConverter.SingleToInt32Bits(r) + 67L * s + 71L * t);
        delegate* unmanaged[Cdecl]<sbyte, byte, short, ushort, int, uint, long, ulong, float, double, nint, sbyte, short, float, double, byte, double, float, long, int, long> scalars = &Scalars;
        Check.Equal(expected, scalars(a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t), "scalars");
        var scalarsDel = Marshal.GetDelegateForFunctionPointer<ScalarsDel>((IntPtr)scalars);
        Check.Equal(expected, scalarsDel(a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t), "scalars through a delegate");
        delegate* unmanaged[Cdecl]<int, sbyte> retSByte = &RetSByte; Check.Equal((sbyte)e, retSByte(e), "sbyte return");
        delegate* unmanaged[Cdecl]<int, byte> retByte = &RetByte; Check.Equal((byte)e, retByte(e), "byte return");
        delegate* unmanaged[Cdecl]<int, short> retShort = &RetShort; Check.Equal((short)e, retShort(e), "short return");
        delegate* unmanaged[Cdecl]<int, ushort> retUShort = &RetUShort; Check.Equal((ushort)e, retUShort(e), "ushort return");
        delegate* unmanaged[Cdecl]<double, float> retFloat = &RetFloat; Check.Equal(BitConverter.SingleToInt32Bits((float)j), BitConverter.SingleToInt32Bits(retFloat(j)), "float return");
        delegate* unmanaged[Cdecl]<float, Half> retHalf = &RetHalf; Check.Equal(BitConverter.HalfToInt16Bits((Half)i), BitConverter.HalfToInt16Bits(retHalf(i)), "Half return");
        int local = e; delegate* unmanaged[Cdecl]<int*, int*> echoPtr = &EchoPtr; Check.That(echoPtr(&local) == &local, "pointer echo");
        delegate* unmanaged[Cdecl]<Half, Half, Half, Half, Half, Half, Half, Half, Half, Half, long> halves = &Halves;
        Half h0 = (Half)i, h1 = (Half)j, h2 = (Half)n, h3 = (Half)o, h4 = (Half)q, h5 = (Half)r, h6 = BitConverter.Int16BitsToHalf(c), h7 = BitConverter.Int16BitsToHalf((short)d), h8 = BitConverter.Int16BitsToHalf(m), h9 = BitConverter.Int16BitsToHalf((short)e);
        Check.Equal(unchecked(BitConverter.HalfToInt16Bits(h0) + 3L * BitConverter.HalfToInt16Bits(h1) + 5L * BitConverter.HalfToInt16Bits(h2) + 7L * BitConverter.HalfToInt16Bits(h3) + 11L * BitConverter.HalfToInt16Bits(h4) + 13L * BitConverter.HalfToInt16Bits(h5) + 17L * BitConverter.HalfToInt16Bits(h6) + 19L * BitConverter.HalfToInt16Bits(h7) + 23L * BitConverter.HalfToInt16Bits(h8) + 29L * BitConverter.HalfToInt16Bits(h9)), halves(h0, h1, h2, h3, h4, h5, h6, h7, h8, h9), "ten Halves");
    }

    private static void DelegateCases(ref FuzzInput input)
    {
        S16 a = Read<S16>(ref input); S24 b = Read<S24>(ref input);
        delegate* unmanaged[Cdecl]<S16, S16> e16 = &EchoS16; delegate* unmanaged[Cdecl]<S24, S24> e24 = &EchoS24;
        var d16 = Marshal.GetDelegateForFunctionPointer<EchoS16Del>((IntPtr)e16); var d24 = Marshal.GetDelegateForFunctionPointer<EchoS24Del>((IntPtr)e24);
        Check.Equal(Fold(a), Fold(d16(a)), "S16 echo through a delegate"); Check.Equal(Fold(b), Fold(d24(b)), "S24 echo through a delegate");
        // A managed delegate exposed as a function pointer and called through it: the reverse thunk for blittable structs.
        EchoS16Del m16 = s => new S16 { A = s.A + 1, B = s.B * 2 }; EchoS24Del m24 = s => new S24 { A = s.C, B = s.B, C = s.A };
        var f16 = (delegate* unmanaged[Cdecl]<S16, S16>)Marshal.GetFunctionPointerForDelegate(m16); var f24 = (delegate* unmanaged[Cdecl]<S24, S24>)Marshal.GetFunctionPointerForDelegate(m24);
        S16 r16 = f16(a); S24 r24 = f24(b);
        Check.That(r16.A == a.A + 1 && BitConverter.DoubleToInt64Bits(r16.B) == BitConverter.DoubleToInt64Bits(a.B * 2), "S16 through a delegate thunk");
        Check.That(r24.A == b.C && BitConverter.DoubleToInt64Bits(r24.B) == BitConverter.DoubleToInt64Bits(b.B) && r24.C == b.A, "S24 through a delegate thunk");
        GC.KeepAlive(m16); GC.KeepAlive(m24);
    }

    /// <summary>Delegate thunks whose reverse stubs marshal strings and arrays from guarded native memory.</summary>
    private static void ReverseStrings(ref FuzzInput input)
    {
        byte flags = input.Byte();
        byte[] text = input.SegmentBytes().ToArray();
        int[] ints = MemoryMarshal.Cast<byte, int>(input.Bytes(Math.Min(input.Remaining, 64))).ToArray();
        bool atStart = (flags & 1) != 0;
        // UTF-8, NUL last before the guard page.
        byte* utf8 = Guarded.Allocate(text.Length + 1, atStart);
        text.CopyTo(new Span<byte>(utf8, text.Length)); utf8[text.Length] = 0;
        string expected = Encoding.UTF8.GetString(text);
        var strLen = (delegate* unmanaged[Cdecl]<byte*, int>)Marshal.GetFunctionPointerForDelegate(s_strLen);
        Check.Equal(expected.Length, strLen(utf8), "LPUTF8Str callback length"); Check.Equal(expected, s_lastString, "LPUTF8Str callback string");
        Check.Equal(-1, strLen(null), "LPUTF8Str callback null");
        var ansiLen = (delegate* unmanaged[Cdecl]<byte*, int>)Marshal.GetFunctionPointerForDelegate(s_ansiStrLen);
        Check.Equal(expected.Length, ansiLen(utf8), "LPStr callback length"); Check.Equal(expected, s_lastString, "LPStr callback string");
        // UTF-16, NUL char last.
        char[] wide = Encoding.Unicode.GetString(text, 0, text.Length & ~1).ToCharArray();
        int nul = Array.IndexOf(wide, '\0'); if (nul >= 0) wide = wide.AsSpan(0, nul).ToArray();
        char* utf16 = (char*)Guarded.Allocate((wide.Length + 1) * 2L, !atStart);
        wide.CopyTo(new Span<char>(utf16, wide.Length)); utf16[wide.Length] = '\0';
        var wstrLen = (delegate* unmanaged[Cdecl]<char*, int>)Marshal.GetFunctionPointerForDelegate(s_wstrLen);
        Check.Equal(wide.Length, wstrLen(utf16), "LPWStr callback length"); Check.Equal(new string(wide), s_lastString, "LPWStr callback string");
        // [In] int[] with SizeParamIndex from exactly n guarded ints; [Out] int[] written back into exactly n guarded ints.
        int* nativeInts = (int*)Guarded.Allocate(ints.Length * 4L, atStart);
        ints.CopyTo(new Span<int>(nativeInts, ints.Length));
        var sumArr = (delegate* unmanaged[Cdecl]<int*, int, long>)Marshal.GetFunctionPointerForDelegate(s_sumArr);
        long h = 0; foreach (int x in ints) h = unchecked(h * 31 + x);
        Check.Equal(unchecked(h + ints.Length * 1000003L), sumArr(nativeInts, ints.Length), "[In] int[] callback");
        Check.That(s_lastArray is not null && s_lastArray.SequenceEqual(ints), "[In] int[] callback contents");
        Check.Equal(-1000003L, sumArr(null, 3), "[In] int[] callback null");
        var fillArr = (delegate* unmanaged[Cdecl]<int*, int, int, int>)Marshal.GetFunctionPointerForDelegate(s_fillArr);
        int v = flags * 1000;
        Check.Equal(ints.Length, fillArr(nativeInts, ints.Length, v), "[Out] int[] callback");
        for (int i = 0; i < ints.Length; i++) Check.Equal(unchecked(v + i), nativeInts[i], $"[Out] int[] callback element {i}");
        var sumBytes = (delegate* unmanaged[Cdecl]<byte*, int, long>)Marshal.GetFunctionPointerForDelegate(s_sumBytes);
        Check.Equal(unchecked(Fold(text) + text.Length * 1000003L), sumBytes(utf8, text.Length), "[In] byte[] callback");
        // A string returned from a callback is a CoTaskMem UTF-8 copy the caller owns.
        var retStr = (delegate* unmanaged[Cdecl]<int, byte*>)Marshal.GetFunctionPointerForDelegate(s_retStr);
        int n = ints.Length > 0 ? ints[0] : flags;
        byte* ret = retStr(n);
        if (n < 0) Check.That(ret == null, "null string return");
        else { Check.Equal(new string('x', n % 100) + n, Marshal.PtrToStringUTF8((IntPtr)ret), "string return"); Marshal.FreeCoTaskMem((IntPtr)ret); }
        GC.KeepAlive(s_strLen); GC.KeepAlive(s_wstrLen); GC.KeepAlive(s_ansiStrLen); GC.KeepAlive(s_sumArr); GC.KeepAlive(s_fillArr); GC.KeepAlive(s_sumBytes); GC.KeepAlive(s_retStr);
    }

    /// <summary>Delegate thunks marshalling bools, chars, by-ref values and non-blittable structs.</summary>
    private static void ReverseValues(ref FuzzInput input)
    {
        byte ba = input.Byte(); int bb = input.Int32(); int bc = input.Int32(); byte bd = input.Byte();
        var bools = (delegate* unmanaged[Cdecl]<byte, int, int, sbyte, int>)Marshal.GetFunctionPointerForDelegate(s_bools);
        Check.Equal((ba != 0 ? 1 : 0) | (bb != 0 ? 2 : 0) | (bc != 0 ? 4 : 0) | (bd != 0 ? 8 : 0), bools(ba, bb, bc, (sbyte)bd), "bool callback");
        // char in an unmanaged function pointer signature would be marshalled as ANSI by the caller, so the raw UTF-16 units go through ushort.
        ushort ca = input.UInt16(); byte cb = (byte)(input.Byte() & 0x7F); ushort cc = input.UInt16();
        var chars = (delegate* unmanaged[Cdecl]<ushort, byte, ushort, int>)Marshal.GetFunctionPointerForDelegate(s_chars);
        Check.Equal(ca + 3 * cb + 5 * cc, chars(ca, cb, cc), "char callback");
        int x = input.Int32(); double z = BitConverter.Int64BitsToDouble((long)input.Int32() << 32 | (uint)input.Int32());
        var rec = new NonBlit { Key = input.Int32(), Flag = (input.Byte() & 1) != 0, Name = new string((char)('a' + input.Byte() % 26), input.Byte() % 6), D = z };
        int size = Marshal.SizeOf<NonBlit>();
        byte* native = Guarded.Allocate(size, (x & 1) != 0);
        Marshal.StructureToPtr(rec, (IntPtr)native, false);
        int nx = x; long ny = 0;
        var refs = (delegate* unmanaged[Cdecl]<int*, long*, double*, byte*, long>)Marshal.GetFunctionPointerForDelegate(s_refs);
        long expected = unchecked(x * 7L + BitConverter.DoubleToInt64Bits(z) + rec.Key + (rec.Flag ? 1 : 0) + rec.Name.Length);
        Check.Equal(expected, refs(&nx, &ny, &z, native), "ref callback result");
        Check.Equal(unchecked(x + 1), nx, "ref int written back"); Check.Equal(expected, ny, "out long written back");
        NonBlit after = Marshal.PtrToStructure<NonBlit>((IntPtr)native);
        Check.That(after.Key == unchecked(rec.Key * 2) && after.Flag == !rec.Flag && after.Name == "ok" && BitConverter.DoubleToInt64Bits(after.D) == BitConverter.DoubleToInt64Bits(z), $"ref NonBlit written back: {after.Key} {after.Flag} {after.Name} {after.D}");
        // By value: the native caller passes the struct's native layout on the stack (24 bytes: MEMORY class).
        var structVal = (delegate* unmanaged[Cdecl]<NativeNonBlit, int, long>)Marshal.GetFunctionPointerForDelegate(s_structVal);
        Marshal.StructureToPtr(rec, (IntPtr)native, false);
        NativeNonBlit nn = *(NativeNonBlit*)native;
        Check.Equal(unchecked(rec.Key + x * 1000003L + (rec.Flag ? 1 : 0) + rec.Name.Length * 7 + BitConverter.DoubleToInt64Bits(rec.D)), structVal(nn, x), "non-blittable struct by value callback");
        GC.KeepAlive(s_bools); GC.KeepAlive(s_chars); GC.KeepAlive(s_refs); GC.KeepAlive(s_structVal);
    }

    /// <summary>The native layout of NonBlit (int, byte, 6 chars, padding, double): 24 bytes.</summary>
    [StructLayout(LayoutKind.Explicit, Size = 24)] public struct NativeNonBlit { [FieldOffset(0)] public int Key; [FieldOffset(4)] public byte Flag; [FieldOffset(16)] public double D; }
}
